import{_ as e,o as a,c as r,ai as s}from"./chunks/framework.Ba-VnP44.js";const c=JSON.parse('{"title":"应用矩阵","description":"","frontmatter":{},"headers":[],"relativePath":"apps/index.md","filePath":"apps/index.md"}'),d={name:"apps/index.md"};function i(p,t,n,o,h,l){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="应用矩阵" tabindex="-1">应用矩阵 <a class="header-anchor" href="#应用矩阵" aria-label="Permalink to “应用矩阵”">​</a></h1><p>从业务需求出发，用软件、AI 与自动化解决真实问题。这里同时收<strong>技术实践</strong>（怎么做）与<strong>项目实例</strong>（做成了什么）。</p><p>五类分类轴，顺序固定为 01 → 05：<strong>AI 智能应用 · 工业数字化应用 · 企业业务应用 · 效率与自动化工具 · 多端应用与现场交付</strong>。每个功能只在一个地方出现 —— 有独立系统、有数据模型、需权限留痕的归前三类；寄生在别人系统上、只做搬运/提醒/生成的归第四类；端上技术与交付形态归第五类。项目实例总表见<a href="/my-vitepress-site/instances/">实例总览</a>。</p><p><strong>项目状态图例</strong>：✅ 已验证（有运行/测试证据） · 🔧 验证中/在建（代码存在，证据整理中） · 📋 规划中（尚未开始）</p><h2 id="已验证项目" tabindex="-1">已验证项目 <a class="header-anchor" href="#已验证项目" aria-label="Permalink to “已验证项目”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>分类</th><th>一句话</th><th>证据</th></tr></thead><tbody><tr><td><a href="/my-vitepress-site/apps/ai/modeldesk.html">ModelDesk · 本机多模态 AI 配测台</a></td><td>01 AI 智能应用</td><td>多个模型 API 收敛成本地 OpenAI 兼容网关：接入、对比、批量运行一体化</td><td>93 项单测通过 · smoke 2/2 · 生产构建成功 · v0.2.1 已发布（MIT）</td></tr></tbody></table><p>在建项目（OpenBiz 工单系统、个人知识库、Java Agent 示例）与各分类规划见对应分类页。</p><h2 id="分类" tabindex="-1">分类 <a class="header-anchor" href="#分类" aria-label="Permalink to “分类”">​</a></h2><table tabindex="0"><thead><tr><th>序</th><th>分类</th><th>定位</th><th>内容</th></tr></thead><tbody><tr><td>01</td><td><a href="/my-vitepress-site/apps/ai/">AI 智能应用</a></td><td>利用人工智能</td><td>模型接入、知识库 RAG、智能体工作流、AI 助手与编程提效</td></tr><tr><td>02</td><td><a href="/my-vitepress-site/apps/industrial/">工业数字化应用</a></td><td>数字化生产</td><td>MES、PLC 采集、设备监控、工业物联网与现场速查</td></tr><tr><td>03</td><td><a href="/my-vitepress-site/apps/business/">企业业务应用</a></td><td>管理企业</td><td>CRM、ERP、OA、BPM、管理后台；<a href="/my-vitepress-site/apps/integration/">系统集成</a>与 <a href="/my-vitepress-site/apps/openbiz/">OpenBiz 骨架</a>也归此类</td></tr><tr><td>04</td><td><a href="/my-vitepress-site/apps/office/">效率与自动化工具</a></td><td>提升效率、减少重复劳动</td><td>飞书/企微机器人、审批待办、个人效率</td></tr><tr><td>05</td><td><a href="/my-vitepress-site/apps/terminal/">多端应用与现场交付</a></td><td>把系统送到手上、装到机器旁</td><td>PDA 与扫码采集、小程序、Electron 桌面端、C# 上位机、离线协同</td></tr></tbody></table><blockquote><p>左侧侧栏只到两级：<strong>分类 → 已开发项目</strong>。实践文章不进侧栏，按分类收进上表各「分类总览」页（如 <a href="/my-vitepress-site/apps/ai/">01 AI 智能应用</a>）；05 暂无项目实例，直接从分类总览进入。</p><p>部署与运维相关内容已归入 <a href="/my-vitepress-site/apps/ops/">技术体系 › 部署与运维</a>，页面地址不变。</p></blockquote><h2 id="定位说明" tabindex="-1">定位说明 <a class="header-anchor" href="#定位说明" aria-label="Permalink to “定位说明”">​</a></h2><ul><li><strong>应用矩阵</strong> 与 <a href="/my-vitepress-site/ai/">AI 学习</a> 分工不同：这里看<strong>做出来的东西</strong>（应用与项目），AI 学习看<strong>怎么用 AI</strong>（工具选择、工作流、复盘）。</li><li>行业内的 AI 能力不单独立类：MES 的 AI 质检留在 02，CRM 的 AI 跟进留在 03，只在页内标注「AI 增强」，避免 AI 类变成万能筐。</li><li>不为填满分类刻意开发项目。先把已有的真实项目和工作经验整理出来，再逐步补充新案例。</li><li>以后无论做微信小程序、飞书机器人、AI Agent，还是 C# 上位机，都能落进这五类，网站不会因新技术出现而频繁改版。</li></ul><hr><p>上一级：首页</p>',14)])])}const f=e(d,[["render",i]]);export{c as __pageData,f as default};
